\label{lem:stars}
For a probability measure $\nu$ on $[0,\pi]$, the cyclic monotonicity inequalities hold if and only if there is a real scalar $\varphi_0$ satisfying
\begin{equation}
\label{eq:star-feasible}
 -\bar c_{t0}(\nu)\leq(1-q^t)\varphi_0\leq\bar c_{0t}(\nu),
 \qquad\text{for every integer }t\geq1.
\end{equation}
In that case, we may choose $\varphi_i=q^i\varphi_0$.

\label{prop:fixed-domain-rate}
For $s>1$, problem~\eqref{eq:disk-rate-lp} attains its maximum, and every optimal measure is supported on the circle $|z|^2=q_\star(s)$.
For each $q\in(0,1)$, membership in $\mathcal Q(s)$ is equivalent to the
existence of a feasible disk measure supported on $|z|^2=q$.
Consequently,
\begin{equation}
\label{eq:qcyc}
 q_\star(s)=\max\mathcal Q(s),
 \qquad q_{\mathrm{quad}}(s)\leqq_\star(s)\leq1-1/s.
\end{equation}

\label{thm:main}
For every $\kappa>1$, the two worst-case asymptotic factors defined in Section~\ref{sec:problem} satisfy
\begin{equation}
\label{eq:main}
 \rho_{\mathrm{fix}}(\kappa)=\rho_{\mathrm{hor}}(\kappa)=q_\star(\sqrt\kappa).
\end{equation}
This factor is attained by a single function in a finite-dimensional space and an initial point, both independent of the iteration count.
The exact rate satisfies
\begin{equation}
\label{eq:classical-bracket}
 \left(1-\frac{1}{\sqrt\kappa}\right)^2
 \leq q_\star(\sqrt\kappa)
 \leq 1-\frac{1}{\sqrt\kappa}.
\end{equation}
In particular, the rate tends to zero as $\kappa\downarrow1$ and to one as $\kappa\to\infty$.

\label{cor:large-kappa}
The exact factor satisfies
\begin{equation}
\label{eq:large-kappa}
 \lim_{\kappa\to\infty}
 \sqrt\kappa\left(1-q_\star(\sqrt\kappa)\right)=\frac43,
 \qquad
 q_\star(\sqrt\kappa)
 =1-\frac{4}{3\sqrt\kappa}+o(\kappa^{-1/2}).
\end{equation}
The corresponding asymptotic factor for the distance $\|x_t-x_\star\|$ is
$1-2/(3\sqrt\kappa)+o(\kappa^{-1/2})$.

\label{cor:metrics}
Replacing $R_t(f,x_0)$ in the two asymptotic factor definitions \eqref{eq:rho-fix}--\eqref{eq:rho-hor} by either
\[
 \frac{f(x_t)-f(x_\star)}{f(x_0)-f(x_\star)}
 \qquad\text{or}\qquad
 \frac{\|\nabla f(x_t)\|^2}{\|\nabla f(x_0)\|^2}
\]
gives the same exact factor as in Theorem~\ref{thm:main}.
The asymptotic factors for the distance $\|x_t-x_\star\|$ and the gradient norm $\|\nabla f(x_t)\|$ equal the square root of this factor.

\label{lem:closed-rate-problem}
For $s>1$, the set $\mathcal Q(s)$ in \eqref{eq:feasible-factors} is nonempty and has a largest element.
Every feasible factor $q$ satisfies $q\leq1-1/s$.

\label{lem:disk-radial-reweighting}
Let $\mu$ be feasible for \eqref{eq:disk-rate-lp} with $m=J(\mu)>0$.
Define $d\eta(z)=|z|^2\,d\mu(z)/m$, which gives greater relative weight to larger values of $|z|^2$.
Then $\eta$ is feasible for the same problem and
\begin{equation}
\label{eq:disk-variance-improvement}
 J(\eta)-J(\mu)
 =\frac{\int |z|^4\,d\mu-m^2}{m}
 =\frac{\operatorname{Var}_\mu(|z|^2)}{m}.
\end{equation}

\label{prop:disk-finite-dual}
Each $q_{\mathrm{rel},n}(s)$ is attained, and
\[
 \alpha_s=q_{\mathrm{rel},0}(s)\geq q_{\mathrm{rel},1}(s)\geq\cdots\geqq_\star(s),
 \qquad \lim_{n\to\infty}q_{\mathrm{rel},n}(s)=q_\star(s).
\]
Moreover,
\begin{equation}
\label{eq:disk-polynomial-dual}
 q_\star(s)=\inf\left\{b:
 \begin{array}{l}
  \Gamma_0\subset\Gamma\text{ finite},\quad\lambda_\gamma\geq0,\\
  b-|z|^2-\displaystyle\sum_{\gamma\in\Gamma_0}
       \lambda_\gamma\mathcal C_\gamma^s(z)\geq0,
       \quad z\in D_s
 \end{array}\right\}.
\end{equation}
The dual constraint requires a real polynomial in $\operatorname{Re}z$ and $\operatorname{Im}z$ to be nonnegative on $D_s$.
For every $b>q_\star(s)$ such a polynomial can be strictly positive on $D_s$.
No finite dual attainment at $b=q_\star(s)$ is asserted.

\label{lem:finite-optimal-support}
Fix $s>1$ and suppose $q_\star(s)>q_{\mathrm{quad}}(s)$.
There are a probability measure $\nu_\star$ supported on finitely many angles in $[0,\pi]$ and a real scalar $\varphi_0^\star$ that satisfy \eqref{eq:star-feasible} at $q=q_\star(s)$.

\label{prop:kyp-time-domain}
There exist a real symmetric matrix $P$ and $\delta>0$ such that
\begin{equation}
\label{eq:kyp-lmi}
 K(P)\doteq
 \begin{bmatrix}
  A^TPA-P&A^TPB\\B^TPA&B^TPB
 \end{bmatrix}
 +\begin{bmatrix}C^T\\D^T\end{bmatrix}
  \widehat M
  \begin{bmatrix}C&D\end{bmatrix}
 \preceq-\delta I.
\end{equation}
Along every trajectory of \eqref{eq:kyp-realization}, the quadratic form $V_P(\xi)\doteq\xi^TP\xi$ satisfies
\begin{equation}
\label{eq:kyp-one-step-balance}
 V_P(\xi_{t+1})-V_P(\xi_t)+o_t^T\widehat M o_t
 \leq-\delta(\|\xi_t\|^2+\|v_t\|^2).
\end{equation}

The strict discrete KYP equivalence~\citep{rantzer1996kyp}, also used in \citet[equation~(21) and the proof of Theorem~4.5]{zhang2019noncausal}, gives a real symmetric $P$ such that $K(P)\prec0$.
Thus $K(P)\preceq-\delta I$ for some $\delta>0$.
For one step of \eqref{eq:kyp-realization}, expansion gives the identity
\begin{equation}
\label{eq:kyp-exact-balance}
 V_P(\xi_{t+1})-V_P(\xi_t)+o_t^T\widehat M o_t
 =\begin{bmatrix}\xi_t\\v_t\end{bmatrix}^{\!T}
 K(P)
 \begin{bmatrix}\xi_t\\v_t\end{bmatrix}.
\end{equation}
Applying \eqref{eq:kyp-lmi} proves \eqref{eq:kyp-one-step-balance}.

\label{cor:kyp-positive-energy}
Suppose $P\succ0$ satisfies \eqref{eq:kyp-lmi}.
Set $R=P^{1/2}$ and $\eta_t=R\xi_t$, so $V_P(\xi_t)=\|\eta_t\|^2$.
Along a rescaled NAG trajectory satisfying the local inequalities \eqref{eq:scaled-local-supply},
\begin{equation}
\label{eq:kyp-euclidean-balance}
 \|\eta_{t+1}\|^2
 \leq\|\eta_t\|^2+b_0\|e_t\|^2
 -\delta(\|R^{-1}\eta_t\|^2+\|v_t\|^2).
\end{equation}
Whenever $e_t=0$, the squared norm cannot increase at that step.

\label{prop:self-similar-energy}
Define
\[
 P_\theta=\begin{bmatrix}1&-\cos\theta\\-\cos\theta&1\end{bmatrix},
 \qquad
 R_\theta=\begin{bmatrix}1&-\cos\theta\\0&\sin\theta\end{bmatrix}.
\]
Then $P_\theta=R_\theta^TR_\theta\succ0$ and
\begin{equation}
\label{eq:modal-energy}
 A_\theta^TP_\theta A_\theta=P_\theta,
 \qquad
 E_t\doteq\xi_t^TP_\theta\xi_t=E_0.
\end{equation}
Moreover,
\begin{equation}
\label{eq:modal-rotation}
 R_\theta A_\theta R_\theta^{-1}
 =\begin{bmatrix}
   \cos\theta&-\sin\theta\\
   \sin\theta&\cos\theta
  \end{bmatrix}.
\end{equation}

\label{prop:kyp-equality-frequencies}
If $\nu_\star$ is feasible at $q$, then
\begin{equation}
\label{eq:contact-support}
 \operatorname{supp}\nu_\star
 \subseteq\{\theta\in[0,\pi]:\phi_\star(\theta)=0\}.
\end{equation}
Assume in addition that a symmetric $P=P^T$ satisfies $K_\star(P)\preceq0$.
For every $\theta\in[0,\pi]$ with $\phi_\star(\theta)=0$ and every nonzero complex input vector $a$, define
\[
 h_\theta(a)=
 \begin{bmatrix}
  (e^{i\theta}I-A)^{-1}Ba\\a
 \end{bmatrix}.
\]
Then
\begin{equation}
\label{eq:contact-kyp-kernel}
 K_\star(P)h_\theta(a)=0.
\end{equation}

\label{prop:rate-not-radical}
The factor $q_\star(s_\dagger)$ is the unique real zero of $F$ in the rational
interval
\begin{equation}
\label{eq:radical-root-interval}
 I\doteq(0.025917757838352596,\;0.025917757838352597).
\end{equation}
The polynomial $F$ is irreducible over $\mathbb Q$ and its splitting-field
Galois group is $S_{20}$. In particular, $q_\star(s_\dagger)$ has algebraic
degree $20$ and is not expressible by radicals over $\mathbb Q$.
